ROCKSPEC := $(wildcard kong-plugin-signoz-*.rockspec)

.PHONY: help install pack upload clean up down restart

help:
	@echo "Targets:"
	@echo "  install     luarocks make — installs into the local tree"
	@echo "  pack        luarocks pack — emits a .src.rock"
	@echo "  upload      luarocks upload (LUAROCKS_API_KEY required)"
	@echo "  clean       Remove .rock artefacts"
	@echo "  up          Start docs/examples/ docker compose"
	@echo "  down        Stop docs/examples/ docker compose"

install:
	luarocks make $(ROCKSPEC)

pack:
	luarocks pack $(ROCKSPEC)

upload:
	@if [ -z "$$LUAROCKS_API_KEY" ]; then \
		echo "LUAROCKS_API_KEY env var required"; exit 1; \
	fi
	luarocks upload $(ROCKSPEC) --api-key=[REDACTED]

clean:
	rm -f *.rock

up:
	cd docs/examples && docker compose up -d

down:
	cd docs/examples && docker compose down

rockspec_format = "3.0"
package = "kong-plugin-signoz"
version = "0.0.1-1"
supported_platforms = { "linux", "macosx" }
source = {
   url = "git+https://github.com/SigNoz/kong-plugin-signoz.git",
   tag = "v0.0.1"
}
description = {
   summary    = "Kong plugin that emits OTLP traces and logs to SigNoz.",
   homepage   = "https://github.com/SigNoz/kong-plugin-signoz",
   license    = "Apache 2.0",
   maintainer = "SigNoz Marketplaces <marketplaces@signoz.io>",
   issues_url = "https://github.com/SigNoz/kong-plugin-signoz/issues",
   labels     = { "kong", "kong-plugin", "observability", "opentelemetry", "otlp", "signoz", "tracing", "logging" }
}
dependencies = {}
build = {
   type = "builtin",
   modules = {
      ["kong.plugins.signoz.handler"]         = "kong/plugins/signoz/handler.lua",
      ["kong.plugins.signoz.schema"]          = "kong/plugins/signoz/schema.lua",
      ["kong.plugins.signoz.meta"]            = "kong/plugins/signoz/meta.lua",
      ["kong.plugins.signoz.kong_compat"]     = "kong/plugins/signoz/kong_compat.lua",
      ["kong.plugins.signoz.conf_builder"]    = "kong/plugins/signoz/conf_builder.lua",
      ["kong.plugins.signoz.logs"]            = "kong/plugins/signoz/logs/init.lua",
      ["kong.plugins.signoz.logs.protobuf"]   = "kong/plugins/signoz/logs/protobuf.lua",
      ["kong.plugins.signoz.logs.json"]       = "kong/plugins/signoz/logs/json.lua",
      ["kong.plugins.signoz.logs.exporter"]   = "kong/plugins/signoz/logs/exporter.lua",
      ["kong.plugins.signoz.traces"]          = "kong/plugins/signoz/traces/init.lua"
   }
}

local PLUGIN_NAME = "signoz"

local validate do
  local validate_entity = require("spec.helpers").validate_plugin_config_schema
  local plugin_schema = require("kong.plugins." .. PLUGIN_NAME .. ".schema")

  function validate(data)
    return validate_entity(data, plugin_schema)
  end
end


describe(PLUGIN_NAME .. ": (schema)", function()

  it("accepts a cloud config with exporter.key", function()
    local ok, err = validate({
      exporter = {
        endpoint = "https://ingest.us.signoz.cloud:443",
        key = "test-key",
      },
    })
    assert.is_nil(err)
    assert.is_truthy(ok)
  end)

  it("accepts a self-hosted config without exporter.key", function()
    local ok, err = validate({
      exporter = {
        endpoint = "http://signoz-otel-collector:4318",
      },
    })
    assert.is_nil(err)
    assert.is_truthy(ok)
  end)

  it("rejects missing exporter.endpoint", function()
    local ok, err = validate({ exporter = { key = "test-key" } })
    assert.is_falsy(ok)
    assert.is_truthy(err)
  end)

  it("rejects missing exporter block entirely", function()
    local ok, err = validate({ resource = { service_name = "kong" } })
    assert.is_falsy(ok)
    assert.is_truthy(err)
  end)

  it("rejects sampling_rate out of range", function()
    local ok, err = validate({
      exporter = { endpoint = "http://localhost:4318" },
      traces = { sampling_rate = 2.0 },
    })
    assert.is_falsy(ok)
    assert.is_truthy(err)
  end)

  it("supplies sensible defaults across all groups", function()
    local ok, _, conf = validate({
      exporter = { endpoint = "http://localhost:4318" },
    })
    assert.is_truthy(ok)
    assert.equals("kong", conf.config.resource.service_name)
    assert.is_true(conf.config.traces.enabled)
    assert.equals(1.0, conf.config.traces.sampling_rate)
    assert.same({ "off" }, conf.config.logs.instrumentations)
    assert.equals(1000, conf.config.exporter.connect_timeout)
    assert.equals(5000, conf.config.exporter.send_timeout)
    assert.equals(5000, conf.config.exporter.read_timeout)
    assert.equals(200, conf.config.exporter.queue.max_batch_size)
    assert.equals(10000, conf.config.exporter.queue.max_entries)
  end)

  it("accepts logs.instrumentations=[access, runtime]", function()
    local ok, err = validate({
      exporter = { endpoint = "http://localhost:4318" },
      logs = { instrumentations = { "access", "runtime" } },
    })
    assert.is_nil(err)
    assert.is_truthy(ok)
  end)

  it("rejects unknown logs.instrumentations sub-type", function()
    local ok, err = validate({
      exporter = { endpoint = "http://localhost:4318" },
      logs = { instrumentations = { "access", "bogus" } },
    })
    assert.is_falsy(ok)
    assert.is_truthy(err)
  end)

  it("accepts user-tuned exporter.queue + timeouts", function()
    local ok, err = validate({
      exporter = {
        endpoint = "http://localhost:4318",
        connect_timeout = 500,
        send_timeout    = 2500,
        read_timeout    = 2500,
        queue = {
          max_batch_size       = 50,
          max_coalescing_delay = 1,
        },
      },
    })
    assert.is_nil(err)
    assert.is_truthy(ok)
  end)

end)
